import React, { useState, useEffect, useMemo, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Menu, Search, SlidersHorizontal, User, ShoppingCart, 
  Star, Plus, Minus, Home, LayoutGrid, Tag, User2, Info 
} from 'lucide-react';
import { categories, products, offers } from './data/menu';

const App = () => {
  const [activeCategory, setActiveCategory] = useState('all');
  const [sandwichOnly, setSandwichOnly] = useState(false);
  const [cart, setCart] = useState({});
  const [searchQuery, setSearchQuery] = useState('');
  const [scrolled, setScrolled] = useState(false);
  const [activeOffer, setActiveOffer] = useState(0);
  const offerRef = useRef(null);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Auto-slide offers
  useEffect(() => {
    const timer = setInterval(() => {
      setActiveOffer((prev) => (prev + 1) % offers.length);
    }, 4000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    if (offerRef.current) {
      offerRef.current.scrollTo({
        left: activeOffer * (offerRef.current.offsetWidth - 40),
        behavior: 'smooth'
      });
    }
  }, [activeOffer]);

  const filteredProducts = useMemo(() => {
    return products.filter(product => {
      const matchesCategory = activeCategory === 'all' || product.category === activeCategory;
      const matchesSearch = product.name.toLowerCase().includes(searchQuery.toLowerCase());
      const isSandwichRelated = ['sandwich', 'grill', 'special-grill', 'jumbo-grill'].includes(product.category);
      const matchesSandwichToggle = !sandwichOnly || isSandwichRelated;

      return matchesCategory && matchesSearch && matchesSandwichToggle;
    });
  }, [activeCategory, searchQuery, sandwichOnly]);

  const updateCart = (id, delta) => {
    setCart(prev => {
      const newQty = (prev[id] || 0) + delta;
      if (newQty <= 0) {
        const { [id]: _, ...rest } = prev;
        return rest;
      }
      return { ...prev, [id]: newQty };
    });
  };

  return (
    <div className="max-w-[480px] mx-auto min-h-screen bg-background pb-32 selection:bg-primary/20">
      {/* HEADER */}
      <header className={`fixed top-0 left-0 right-0 z-[60] transition-all duration-500 ${
        scrolled ? 'glass-effect py-2 shadow-lg shadow-black/5' : 'bg-transparent py-5'
      }`}>
        <div className="max-w-[480px] mx-auto px-5 flex items-center justify-between">
          <motion.button whileTap={{ scale: 0.9 }} className="p-2 -ml-2">
            <Menu size={24} className="text-slate-800" />
          </motion.button>

          <div className="flex flex-col items-center">
            <motion.span 
              layout
              className="text-primary font-black text-2xl tracking-tighter"
            >
              BITES
            </motion.span>
            {!scrolled && (
              <motion.span 
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                className="text-[9px] text-slate-400 font-bold tracking-[0.2em] uppercase"
              >
                Premium Food
              </motion.span>
            )}
          </div>

          <div className="flex items-center gap-1">
            <motion.button whileTap={{ scale: 0.9 }} className="relative p-2">
              <ShoppingCart size={24} className="text-slate-800" />
              <AnimatePresence>
                {Object.keys(cart).length > 0 && (
                  <motion.span 
                    initial={{ scale: 0 }}
                    animate={{ scale: 1 }}
                    exit={{ scale: 0 }}
                    className="absolute top-1 right-1 bg-primary text-white text-[10px] font-black w-5 h-5 rounded-full flex items-center justify-center border-2 border-white"
                  >
                    {Object.values(cart).reduce((a, b) => a + b, 0)}
                  </motion.span>
                )}
              </AnimatePresence>
            </motion.button>
            <motion.button whileTap={{ scale: 0.9 }} className="p-2 -mr-2">
              <User size={24} className="text-slate-800" />
            </motion.button>
          </div>
        </div>
      </header>

      <main className="pt-24 px-5">
        {/* SEARCH SECTION */}
        <section className="mb-8">
          <div className="relative mb-5 group">
            <div className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400 transition-colors group-focus-within:text-primary">
              <Search size={20} />
            </div>
            <input 
              type="text"
              placeholder="Search sandwiches, burgers, pizzas..."
              className="w-full bg-white h-16 pl-14 pr-14 rounded-3xl shadow-sm border-2 border-transparent focus:border-primary/10 focus:ring-4 focus:ring-primary/5 transition-all outline-none text-slate-700 font-medium placeholder:text-slate-300"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
            <div className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-400">
              <SlidersHorizontal size={20} />
            </div>
          </div>

          {/* VEG ONLY TOGGLE (Inspired by Toing) */}
          <div className="flex items-center justify-between bg-white/50 p-1 rounded-2xl w-fit border border-white">
            <button 
              onClick={() => setSandwichOnly(!sandwichOnly)}
              className={`flex items-center gap-2 px-4 py-2.5 rounded-xl transition-all duration-300 ${
                sandwichOnly ? 'bg-primary text-white shadow-md shadow-primary/20' : 'bg-transparent text-slate-600'
              }`}
            >
              <span className="text-sm font-bold">🥪 Sandwich Only</span>
              <div className={`w-8 h-4 rounded-full relative border ${sandwichOnly ? 'bg-white/20 border-white/30' : 'bg-slate-200 border-slate-300'}`}>
                <motion.div 
                  animate={{ x: sandwichOnly ? 16 : 2 }}
                  className={`absolute top-0.5 w-2.5 h-2.5 rounded-full ${sandwichOnly ? 'bg-white' : 'bg-slate-400'}`}
                />
              </div>
            </button>
          </div>
        </section>

        {/* OFFERS HERO */}
        <section className="mb-10 -mx-5 overflow-hidden">
          <div 
            ref={offerRef}
            className="flex gap-4 overflow-x-auto no-scrollbar px-5 py-2 scroll-smooth"
          >
            {offers.map((offer, i) => (
              <motion.div 
                key={offer.id}
                whileTap={{ scale: 0.97 }}
                className="min-w-[85%] h-44 rounded-3xl relative overflow-hidden shadow-xl"
              >
                <img src={offer.image} alt={offer.title} className="absolute inset-0 w-full h-full object-cover" />
                <div className={`absolute inset-0 bg-gradient-to-r ${offer.color.replace('bg-', 'from-')}/80 to-transparent flex flex-col justify-center px-8`}>
                  <motion.span 
                    initial={{ x: -20, opacity: 0 }}
                    whileInView={{ x: 0, opacity: 1 }}
                    className="text-white/80 text-xs font-black uppercase tracking-widest mb-1"
                  >
                    Special Offer
                  </motion.span>
                  <h3 className="text-white font-black text-2xl leading-none mb-1">{offer.title}</h3>
                  <p className="text-white/90 text-sm font-bold">{offer.subtitle}</p>
                </div>
              </motion.div>
            ))}
          </div>
          <div className="flex justify-center gap-2 mt-5">
            {offers.map((_, i) => (
              <motion.div 
                key={i} 
                animate={{ width: i === activeOffer ? 24 : 8 }}
                className={`h-2 rounded-full transition-colors duration-300 ${i === activeOffer ? 'bg-primary' : 'bg-slate-200'}`} 
              />
            ))}
          </div>
        </section>

        {/* CATEGORY SECTION */}
        <section className="mb-10">
          <div className="flex items-center justify-between mb-5">
            <h2 className="font-black text-xl text-slate-800 tracking-tight">Top Categories</h2>
            <button className="text-primary text-xs font-bold uppercase tracking-widest">View All</button>
          </div>
          <div className="flex gap-5 overflow-x-auto no-scrollbar -mx-5 px-5">
            {categories.map((cat) => (
              <motion.button
                key={cat.id}
                whileTap={{ scale: 0.9 }}
                onClick={() => setActiveCategory(cat.id)}
                className="flex flex-col items-center gap-3 min-w-[72px]"
              >
                <div className={`w-[72px] h-[72px] rounded-3xl flex items-center justify-center text-3xl transition-all duration-300 shadow-sm ${
                  activeCategory === cat.id 
                  ? 'bg-primary text-white shadow-lg shadow-primary/30 scale-110' 
                  : 'bg-white text-slate-700 hover:bg-slate-50'
                }`}>
                  {cat.icon}
                </div>
                <span className={`text-[10px] font-black uppercase tracking-widest text-center leading-tight ${
                  activeCategory === cat.id ? 'text-primary' : 'text-slate-400'
                }`}>
                  {cat.name}
                </span>
              </motion.button>
            ))}
          </div>
        </section>

        {/* FILTER CHIPS (Sticky) */}
        <div className="sticky top-[72px] z-40 bg-background/95 backdrop-blur-md -mx-5 px-5 py-4 mb-8 flex gap-2 overflow-x-auto no-scrollbar border-y border-slate-100/50">
          {['⭐ Best Sellers', '🔥 Popular', '₹ Under 99', '🧀 Cheese Lovers', '🌶️ Spicy'].map((chip) => (
            <motion.button 
              key={chip}
              whileTap={{ scale: 0.95 }}
              className="px-5 py-2.5 bg-white border border-slate-100 rounded-2xl whitespace-nowrap text-xs font-bold text-slate-600 shadow-sm hover:border-primary/20 transition-colors"
            >
              {chip}
            </motion.button>
          ))}
        </div>

        {/* PRODUCT LIST */}
        <section className="space-y-8">
          <AnimatePresence mode='popLayout'>
            {filteredProducts.map((product) => (
              <motion.div
                layout
                initial={{ opacity: 0, scale: 0.95 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={{ opacity: 0, scale: 0.9 }}
                key={product.id}
                className={`flex gap-4 bg-white p-4 rounded-3xl border border-slate-50 transition-all duration-300 ${
                  cart[product.id] ? 'shadow-xl shadow-primary/5 ring-2 ring-primary/5' : 'shadow-sm'
                }`}
              >
                <div className="w-32 h-32 rounded-3xl overflow-hidden flex-shrink-0 relative group">
                  <img 
                    src={`https://images.unsplash.com/photo-${1500000000000 + product.id}?auto=format&fit=crop&w=400&q=80`} 
                    alt={product.name}
                    className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110"
                    onError={(e) => {
                      e.target.src = "https://images.unsplash.com/photo-1528735602780-2552fd46c7af?auto=format&fit=crop&w=400&q=80";
                    }}
                  />
                  {product.veg && (
                    <div className="absolute top-2 left-2 w-4 h-4 border-2 border-green-600 flex items-center justify-center bg-white rounded-sm">
                      <div className="w-1.5 h-1.5 bg-green-600 rounded-full" />
                    </div>
                  )}
                </div>

                <div className="flex-1 flex flex-col py-1">
                  <div className="flex items-center gap-1.5 mb-1.5">
                    <span className="text-[10px] font-black uppercase text-slate-300 tracking-widest">{product.category}</span>
                    <span className="w-1 h-1 bg-slate-200 rounded-full" />
                    <div className="flex items-center gap-0.5">
                      <Star size={10} className="fill-accent text-accent" />
                      <span className="text-[10px] font-bold text-slate-500">{product.rating}</span>
                    </div>
                  </div>

                  <h3 className="font-black text-slate-800 text-lg leading-tight mb-1">{product.name}</h3>
                  <p className="text-xs text-slate-400 line-clamp-2 font-medium leading-relaxed mb-4">{product.description}</p>

                  <div className="mt-auto flex items-center justify-between">
                    <div className="flex flex-col">
                      <span className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">Price</span>
                      <span className="font-black text-slate-900 text-lg">₹{product.price}</span>
                    </div>

                    <div className="relative">
                      <AnimatePresence mode='wait'>
                        {cart[product.id] ? (
                          <motion.div 
                            key="qty"
                            initial={{ width: 40, opacity: 0 }}
                            animate={{ width: 100, opacity: 1 }}
                            exit={{ width: 40, opacity: 0 }}
                            className="flex items-center bg-primary text-white rounded-2xl h-11 px-1 shadow-lg shadow-primary/20"
                          >
                            <button 
                              onClick={() => updateCart(product.id, -1)}
                              className="w-8 h-8 flex items-center justify-center hover:bg-white/10 rounded-xl transition-colors"
                            >
                              <Minus size={16} strokeWidth={3} />
                            </button>
                            <span className="flex-1 text-center font-black text-sm">{cart[product.id]}</span>
                            <button 
                              onClick={() => updateCart(product.id, 1)}
                              className="w-8 h-8 flex items-center justify-center hover:bg-white/10 rounded-xl transition-colors"
                            >
                              <Plus size={16} strokeWidth={3} />
                            </button>
                          </motion.div>
                        ) : (
                          <motion.button
                            key="add"
                            initial={{ opacity: 0, scale: 0.8 }}
                            animate={{ opacity: 1, scale: 1 }}
                            whileTap={{ scale: 0.9 }}
                            onClick={() => updateCart(product.id, 1)}
                            className="h-11 px-8 bg-white border-2 border-primary/20 text-primary font-black text-xs rounded-2xl hover:bg-primary hover:text-white hover:shadow-lg hover:shadow-primary/20 transition-all"
                          >
                            ADD
                          </motion.button>
                        )}
                      </AnimatePresence>
                    </div>
                  </div>
                </div>
              </motion.div>
            ))}
          </AnimatePresence>

          <div className="h-20 flex flex-col items-center justify-center opacity-30">
            <Info size={20} className="mb-2" />
            <p className="text-[10px] font-bold uppercase tracking-[0.3em]">End of Menu</p>
          </div>
        </section>
      </main>

      {/* BOTTOM NAVIGATION */}
      <nav className="fixed bottom-8 left-1/2 -translate-x-1/2 w-[92%] max-w-[440px] bg-slate-900/95 backdrop-blur-2xl rounded-[32px] p-2.5 flex items-center justify-between shadow-2xl shadow-black/40 z-[100]">
        {[
          { id: 'home', icon: Home, label: 'Home' },
          { id: 'categories', icon: LayoutGrid, label: 'Browse' },
          { id: 'offers', icon: Tag, label: 'Deals' },
          { id: 'cart', icon: ShoppingCart, label: 'Cart', count: Object.values(cart).reduce((a, b) => a + b, 0) },
        ].map((item) => {
          const isActive = item.id === 'home';
          return (
            <motion.button
              key={item.id}
              whileTap={{ scale: 0.9 }}
              className={`relative flex items-center gap-2.5 px-5 py-3.5 rounded-[24px] transition-all duration-300 ${
                isActive ? 'bg-primary text-white shadow-lg shadow-primary/30' : 'text-slate-500 hover:text-slate-300'
              }`}
            >
              <item.icon size={20} strokeWidth={isActive ? 3 : 2} />
              {isActive && (
                <motion.span 
                  initial={{ width: 0, opacity: 0 }}
                  animate={{ width: 'auto', opacity: 1 }}
                  className="text-xs font-black tracking-wide"
                >
                  {item.label}
                </motion.span>
              )}
              {item.count > 0 && !isActive && (
                <span className="absolute top-2 right-3 w-4 h-4 bg-primary text-white text-[8px] font-black rounded-full flex items-center justify-center border border-slate-900">
                  {item.count}
                </span>
              )}
            </motion.button>
          );
        })}
      </nav>

      {/* CUSTOM CURSOR / TOUCH EFFECT (Optional premium touch) */}
      <div className="fixed inset-0 pointer-events-none z-[200]">
        <div className="w-full h-full opacity-[0.03] bg-[url('https://www.transparenttextures.com/patterns/asfalt-dark.png')]" />
      </div>
    </div>
  );
};

export default App;
